import type { Category, TBRow } from "./types";

export interface AjeLine {
  code: string;
  name: string;
  category: Category | "";
  debit: number;
  credit: number;
}

export interface Aje {
  id: string;
  date: string;
  reason: string;
  author: string;
  lines: AjeLine[];
  /** "AJE" = analyst adjusting entry; "BRIDGE" = framework bridge entry generated by the app. */
  kind: "AJE" | "BRIDGE";
  standardRef?: string;
}

export function ajeBalanced(aje: Aje): boolean {
  const d = aje.lines.reduce((a, l) => a + l.debit - l.credit, 0);
  return Math.abs(d) < 0.005 && aje.lines.length >= 2;
}

/**
 * Applies adjusting entries to the current period. Lines on an existing account code adjust that row;
 * new codes become new rows tagged with the entry id for lineage.
 */
export function applyAjes(rows: TBRow[], ajes: Aje[]): TBRow[] {
  const out = rows.map((r) => ({ ...r }));
  const byCode = new Map(out.map((r, i) => [r.code, i]));
  for (const aje of ajes) {
    if (!ajeBalanced(aje)) continue;
    for (const l of aje.lines) {
      const idx = byCode.get(l.code);
      if (idx !== undefined) {
        const r = out[idx];
        const net = r.currentDebit - r.currentCredit + l.debit - l.credit;
        r.currentDebit = net > 0 ? net : 0;
        r.currentCredit = net < 0 ? -net : 0;
      } else {
        byCode.set(l.code, out.length);
        out.push({
          code: l.code,
          name: l.name,
          category: l.category,
          suggested: false,
          currentDebit: l.debit,
          currentCredit: l.credit,
          priorDebit: 0,
          priorCredit: 0,
          sourceRow: 0,
          sourceDocId: aje.id,
          mappingRule: aje.kind === "BRIDGE" ? `bridge:${aje.standardRef ?? ""}` : `aje:${aje.id}`,
        });
      }
    }
  }
  return out;
}

export type Framework = "EAS" | "IFRS";

export interface BridgeInputs {
  /** Proposed employees' profit share for the period (حصة العاملين في الأرباح). */
  employeeProfitShare: number;
  /** Proposed board remuneration for the period (مكافأة أعضاء مجلس الإدارة). */
  boardRemuneration: number;
}

/**
 * EAS treats employees' profit share and board remuneration as appropriations of profit (statement of changes in equity).
 * IFRS treats them as employee benefits / key management compensation expensed in profit or loss (IAS 19, IAS 24).
 * Under IFRS the app generates bridge entries accruing the expense; under EAS it generates none and the
 * amounts appear as appropriations in the equity statement.
 */
export function bridgeEntries(framework: Framework, b: BridgeInputs, date: string): Aje[] {
  if (framework !== "IFRS") return [];
  const out: Aje[] = [];
  if (b.employeeProfitShare > 0) {
    out.push({
      id: "BRIDGE-IAS19",
      date,
      kind: "BRIDGE",
      standardRef: "IAS 19",
      author: "system",
      reason: "IFRS: employees' profit share recognised as personnel expense (EAS: appropriation in equity).",
      lines: [
        { code: "BR-6901", name: "Employees' profit share expense (IFRS bridge)", category: "ADMIN_EXPENSE", debit: b.employeeProfitShare, credit: 0 },
        { code: "BR-2901", name: "Employees' profit share payable (IFRS bridge)", category: "OTHER_CURRENT_LIABILITY", debit: 0, credit: b.employeeProfitShare },
      ],
    });
  }
  if (b.boardRemuneration > 0) {
    out.push({
      id: "BRIDGE-IAS24",
      date,
      kind: "BRIDGE",
      standardRef: "IAS 24",
      author: "system",
      reason: "IFRS: board remuneration recognised as key management compensation expense (EAS: appropriation in equity).",
      lines: [
        { code: "BR-6902", name: "Board remuneration expense (IFRS bridge)", category: "ADMIN_EXPENSE", debit: b.boardRemuneration, credit: 0 },
        { code: "BR-2902", name: "Board remuneration payable (IFRS bridge)", category: "OTHER_CURRENT_LIABILITY", debit: 0, credit: b.boardRemuneration },
      ],
    });
  }
  return out;
}

export function effectiveRows(rows: TBRow[], ajes: Aje[], framework: Framework, bridge: BridgeInputs, date: string): TBRow[] {
  return applyAjes(rows, [...ajes, ...bridgeEntries(framework, bridge, date)]);
}
